import math

def act(history):
    try:
        states = history['states']
        actions = history['actions']
    except:
        states = history.states
        actions = history.actions
    n = len(actions)
    targets = states[1:]
    def features(s, u, kind):
        x, y = s
        a, b = u
        f = [x, y, a, b]
        if kind == 'linear':
            return f
        f = f + [1.0]
        if kind == 'affine':
            return f
        if kind == 'quadratic':
            return f + [x*x, x*y, y*y]
        if kind == 'radial_cubic':
            r2 = x*x+y*y
            return f + [r2*x, r2*y]
        return f + [math.sin(x), math.sin(y)]
    def fit(F, Y):
        count = len(F)
        p = len(F[0])
        Q = []
        R = [[0.0 for j in range(p)] for i in range(p)]
        for j in range(p):
            v = [F[i][j] for i in range(count)]
            for repeat in range(2):
                for k in range(j):
                    z = sum(Q[k][i]*v[i] for i in range(count))
                    R[k][j] += z
                    v = [v[i]-z*Q[k][i] for i in range(count)]
            d = math.sqrt(sum(z*z for z in v))
            if d < 1e-12:
                return None
            R[j][j] = d
            Q.append([z/d for z in v])
        coefficients = []
        for output in range(2):
            rhs = [sum(Q[j][i]*Y[i][output] for i in range(count)) for j in range(p)]
            c = [0.0]*p
            for j in range(p-1, -1, -1):
                c[j] = (rhs[j]-sum(R[j][k]*c[k] for k in range(j+1,p)))/R[j][j]
            coefficients.append(c)
        return coefficients
    result = {'observations': n, 'current_norm': math.sqrt(sum(z*z for z in states[-1])), 'models': {}}
    menu = [[0.6,0.0],[0.519615242271,0.3],[0.3,0.519615242271],[0.0,0.6],[-0.3,0.519615242271],[-0.519615242271,0.3],[-0.6,0.0],[-0.519615242271,-0.3],[-0.3,-0.519615242271],[0.0,-0.6],[0.3,-0.519615242271],[0.519615242271,-0.3],[0.0,0.0]]
    for kind in ['linear','affine','quadratic','radial_cubic','sine']:
        F = [features(states[i],actions[i],kind) for i in range(n)]
        c = fit(F,targets)
        if c is None:
            continue
        errors = [[sum(F[i][j]*c[k][j] for j in range(len(F[i])))-targets[i][k] for k in range(2)] for i in range(n)]
        entry = {'coefficients': c, 'rms_error': math.sqrt(sum(z*z for e in errors for z in e)/(2*n)), 'max_error': max(abs(z) for e in errors for z in e), 'residuals': errors}
        loo = []
        for i in range(n):
            cc = fit([F[j] for j in range(n) if j != i],[targets[j] for j in range(n) if j != i])
            if cc is not None:
                loo.append([sum(F[i][j]*cc[k][j] for j in range(len(F[i])))-targets[i][k] for k in range(2)])
        if loo:
            entry['loo_rms'] = math.sqrt(sum(z*z for e in loo for z in e)/(2*len(loo)))
            entry['loo_max'] = max(abs(z) for e in loo for z in e)
        entry['next_states'] = [[sum(v*c[k][j] for j,v in enumerate(features(states[-1],u,kind))) for k in range(2)] for u in menu]
        result['models'][kind] = entry
    return result

