        r = math.sqrt(r2)
        if kind in ['rotate_r','rotate_r2','rotate_x','rotate_clock']:
            v = r if kind == 'rotate_r' else r2 if kind == 'rotate_r2' else x if kind == 'rotate_x' else t
            co,si = math.cos(c*v),math.sin(c*v)
            a,b = co*a-si*b,si*a+co*b
        elif kind == 'gain_power':
            g = max(r,1e-8)**c
            a,b = a*g,b*g
        elif kind == 'gain_exp':
            g = math.exp(c*r)
            a,b = a*g,b*g
        elif kind == 'input_tanh':
            a,b = math.tanh(c*a)/c,math.tanh(c*b)/c
        elif kind == 'input_sine':
            a,b = math.sin(c*a)/c,math.sin(c*b)/c
        z = [x,y,a,b]
        if base == 1:
            z.append(1.0)
        elif base == 2:
            z += [x*r2,y*r2]
        if kind == 'poly_x2':
            z += [x*x]
        elif kind == 'poly_x3':
            z += [x*x,x*x*x]
        elif kind == 'poly_x4':
            z += [x*x,x*x*x,x**4]
        elif kind == 'poly_x5':
            z += [x*x,x*x*x,x**4,x**5]
        elif kind == 'quadratic':
            z += [x*x,x*y,y*y]
        elif kind == 'quadratic_cubic':
            z += [x*x,x*y,y*y,x*x*x]
        elif kind == 'component_cubic':
            z += [x*x*x,y*y*y]
        elif kind == 'radial1':
            z += [x*r,y*r]
        elif kind == 'radial12':
            z += [x*r,y*r,x*r2,y*r2]
        elif kind == 'bilinear':
            z += [x*a,x*b,y*a,y*b]
        elif kind == 'radial_input':
            z += [r*a,r*b]
        elif kind == 'quadratic_input':
            z += [a*a,a*b,b*b]
        elif kind == 'sine_state':
            z += [math.sin(c*x),math.sin(c*y)]
        elif kind == 'tanh_state':
            z += [math.tanh(c*x),math.tanh(c*y)]
        elif kind == 'clock_force':
            z += [math.sin(c*t),math.cos(c*t)]
        return z

    def fit(kind,c,base):
        rows = [features(states[i],actions[i],i,kind,c,base) for i in range(n)]
        p = len(rows[0])
        if p >= n:
            return None
        q = []
        rr = [[0.0 for j in range(p)] for k in range(p)]
        conditioning = 1.0
        for j in range(p):
            v = [row[j] for row in rows]
            original = math.sqrt(sum(a*a for a in v))
            for rep in range(2):
                for k in range(j):
                    d = sum(q[k][i]*v[i] for i in range(n))
                    rr[k][j] += d
                    v = [v[i]-d*q[k][i] for i in range(n)]
            norm = math.sqrt(sum(a*a for a in v))
            if norm < 1e-12:
                return None
            conditioning = min(conditioning,norm/max(original,1e-15))
            rr[j][j] = norm
            q.append([a/norm for a in v])
        coef = []
        for d in range(2):
            b = [sum(q[j][i]*states[i+1][d] for i in range(n)) for j in range(p)]
            co = [0.0 for j in range(p)]
            for j in range(p-1,-1,-1):
                co[j] = (b[j]-sum(rr[j][k]*co[k] for k in range(j+1,p)))/rr[j][j]
            coef.append(co)
        residuals = []
        loo = []
        for i in range(n):
            e2 = sum((sum(coef[d][j]*rows[i][j] for j in range(p))-states[i+1][d])**2 for d in range(2))
            residuals.append(math.sqrt(e2))
            leverage = sum(q[j][i]*q[j][i] for j in range(p))
            loo.append(math.sqrt(e2)/max(1e-12,1-leverage))
        rms = math.sqrt(sum(a*a for a in residuals)/n)
        lrms = math.sqrt(sum(a*a for a in loo)/n)
        score = lrms*(1+0.025*p)
        return {'kind':kind,'parameter':c,'base':base,'coef':coef,'rms':rms,'max_residual':max(residuals),'loo_rms':lrms,'loo_max':max(loo),'score':score,'conditioning':conditioning}

    best = {}
    def consider(kind,c,base):
        m = fit(kind,c,base)
        if m is None:
            return
        key = kind+str(base)
        if key not in best or m['score'] < best[key]['score']:
            best[key] = m

    fixed = ['linear','poly_x2','poly_x3','poly_x4','poly_x5','quadratic','quadratic_cubic','component_cubic','radial1','radial12','bilinear','radial_input','quadratic_input']
    for kind in fixed:
        for base in [0,1]:
            consider(kind,0.0,base)
    consider('linear',0.0,2)
    for kind in ['rotate_r','rotate_r2','rotate_x','rotate_clock']:
        for base in [0,1,2]:
            for j in range(-24,25):
                consider(kind,j*0.25,base)
    for kind in ['gain_power','gain_exp']:
        for base in [0,1,2]:
            for j in range(-12,13):
                consider(kind,j*0.25,base)
    for kind in ['input_tanh','input_sine','sine_state','tanh_state','clock_force']:
        for base in [0,1]:
            for j in range(1,33):
                consider(kind,j*0.25,base)
    parameterized = [m for m in best.values() if m['kind'] not in fixed]
    parameterized.sort(key=lambda m:m['score'])
    for old in parameterized[:10]:
        kind,base = old['kind'],old['base']
        key = kind+str(base)
        step = 0.25
        for repeat in range(7):
            center = best[key]['parameter']
            step = step/5.0
            for j in range(-5,6):
                c = center+j*step
                if kind in ['input_tanh','input_sine','sine_state','tanh_state','clock_force'] and c <= 0:
                    continue
                consider(kind,c,base)

    ranked = sorted(best.values(),key=lambda m:m['score'])
    def predict(m,s,u,t):
        z = features(s,u,t,m['kind'],m['parameter'],m['base'])
        return [sum(co[j]*z[j] for j in range(len(z))) for co in m['coef']]

    reports = []
    for m in ranked[:18]:
        report = dict(m)
        report['next_states'] = [predict(m,states[-1],u,n) for u in menu]
        reports.append(report)

    selected = []
    used = {}
    for m in ranked:
        kind = m['kind']
        if kind not in used:
            selected.append(m)
            used[kind] = True
        if len(selected) >= 4:
            break

    def plan(m,first,width):
        s = predict(m,states[-1],menu[first],n)
        r2 = s[0]*s[0]+s[1]*s[1]
        if r2 > 16:
            return {'first':first,'safe_continuation_found':False,'next_norm':math.sqrt(r2)}
        beam = [(s[0],s[1],[first],math.sqrt(r2),0.0)]
        for next_step in range(n+2,33):
            expanded = []
            for x,y,path,peak,late in beam:
                for j in range(13):
                    ns = predict(m,[x,y],menu[j],next_step-1)
                    nr2 = ns[0]*ns[0]+ns[1]*ns[1]
                    if nr2 > 16:
                        continue
                    nr = math.sqrt(nr2)
                    nl = max(late,nr) if next_step >= 28 else 0.0
                    cost = nr2+1000*nl*nl
                    expanded.append((cost,ns[0],ns[1],path+[j],max(peak,nr),nl))
            if not expanded:
                return {'first':first,'safe_continuation_found':False,'survived_through':next_step-1}
            expanded.sort(key=lambda z:z[0])
            beam = []
            seen = {}
            cell = 0.035 if next_step < 25 else 0.003
            for cost,x,y,path,peak,late in expanded:
                key = (int(math.floor(x/cell)),int(math.floor(y/cell)))
                if key in seen:
                    continue
                seen[key] = True
                beam.append((x,y,path,peak,late))
                if len(beam) >= width:
                    break
        winner = min(beam,key=lambda z:(z[4],z[0]*z[0]+z[1]*z[1]))
        return {'first':first,'safe_continuation_found':True,'target_window_max_norm':winner[4],'forecast_success':winner[4] <= 0.05,'peak_norm':winner[3],'terminal':[winner[0],winner[1]],'path':winner[2]}

    plans = []
    for m in selected:
        plans.append({'kind':m['kind'],'parameter':m['parameter'],'base':m['base'],'loo_rms':m['loo_rms'],'candidates':[plan(m,j,24) for j in range(13)]})
    return {'state_norms':[math.sqrt(s[0]*s[0]+s[1]*s[1]) for s in states],'ranked_models':reports,'continuation_search':plans,'planning_note':'Finite-width searches are model-conditioned feasibility witnesses, not proofs of impossibility or calibrated probabilities.'}

def act(history):
    states = history['states']
    actions = history['actions']
    def solve(a, b):
        n = len(b)
        m = [a[i][:] + [b[i]] for i in range(n)]
        for j in range(n):
            k = max(range(j, n), key=lambda i: abs(m[i][j]))
            if abs(m[k][j]) < 1e-18:
                return None
            m[j], m[k] = m[k], m[j]
            v = m[j][j]
            m[j] = [z / v for z in m[j]]
            for i in range(n):
                if i != j:
                    v = m[i][j]
                    m[i] = [m[i][h] - v * m[j][h] for h in range(n + 1)]
        return [m[i][n] for i in range(n)]
    def features(s, u, kind):
        x, y = s
        a, b = u
        f = [x, y, a, b]
        if kind == 'affine':
            return f + [1.0]
        if kind == 'radial_cubic':
            return f + [x * (x*x+y*y), y * (x*x+y*y)]
        if kind == 'radial_cubic_affine':
            return f + [x * (x*x+y*y), y * (x*x+y*y), 1.0]
        if kind == 'separate_cubic':
            return f + [x*x*x, y*y*y]
        if kind == 'quadratic':
            return f + [x*x, x*y, y*y]
        if kind == 'quadratic_affine':
            return f + [x*x, x*y, y*y, 1.0]
        return f
    def fit(fs, ys, ids):
        p = len(fs[0])
        a = [[sum(fs[t][i]*fs[t][j] for t in ids) for j in range(p)] for i in range(p)]
        return [solve(a, [sum(fs[t][i]*ys[t][d] for t in ids) for i in range(p)]) for d in range(2)]
    out = {}
    n = len(actions)
    ys = states[1:]
    for kind in ['linear', 'affine', 'radial_cubic', 'radial_cubic_affine', 'separate_cubic', 'quadratic', 'quadratic_affine']:
        fs = [features(states[t], actions[t], kind) for t in range(n)]
        c = fit(fs, ys, list(range(n)))
        if c[0] is None or c[1] is None:
            continue
        residuals = [[sum(c[d][j]*fs[t][j] for j in range(len(fs[t]))) - ys[t][d] for d in range(2)] for t in range(n)]
        loo = []
        for t in range(n):
            cc = fit(fs, ys, [i for i in range(n) if i != t])
            if cc[0] is not None and cc[1] is not None:
                loo.append(sum((sum(cc[d][j]*fs[t][j] for j in range(len(fs[t]))) - ys[t][d])**2 for d in range(2))**0.5)
        out[kind] = {'coefficients': c, 'residuals': residuals, 'max_fit_error': max(sum(v*v for v in r)**0.5 for r in residuals), 'loo_errors': loo}
    out['state_norms'] = [sum(v*v for v in s)**0.5 for s in states]
    return out

